const token = pm.environment.get("token");
const tokenExpiry = pm.environment.get("tokenExpiry");
const now = Date.now();

// If token exists and is not expired (with 60s buffer), skip re-auth
if (token && tokenExpiry && now < (parseInt(tokenExpiry) - 60000)) {
    console.log("✅ Token is still valid. Skipping re-authentication.");
} else {
    console.log("🔄 Token missing or expired. Fetching a new token...");

    pm.sendRequest({
        url: "https://api.practicesoftwaretesting.com/users/login",
        method: "POST",
        header: {
            "Content-Type": "application/json",
            "Accept": "application/json"
        },
        body: {
            mode: "raw",
            raw: JSON.stringify({
                email: "enyinna15@gmail.com",
                password: "Enyinna_10$"
            })
        }
    }, function (err, res) {
        if (err) {
            console.error("❌ Failed to fetch token:", err);
        } else {
            const jsonResponse = res.json();
            if (jsonResponse && jsonResponse.access_token) {
                pm.environment.set("token", jsonResponse.access_token);
                const expiry = Date.now() + ((jsonResponse.expires_in || 3600) * 1000);
                pm.environment.set("tokenExpiry", expiry);
                console.log("✅ New token fetched and saved to environment variable 'token'");
                console.log("✅ Token expires at:", new Date(expiry).toISOString());
            } else {
                console.error("❌ Login response did not contain access_token:", JSON.stringify(jsonResponse));
            }
        }
    });
}

